<?php
namespace App\Http\Controllers;
use App\Models\{AuditLog,Category,Order,OrderItem,OrderStatusHistory,PaymentSubmission,Product,Reservation,RestaurantSetting,User};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash,RateLimiter,Storage};
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
class StoreController extends Controller {
 private function audit(Request $r,string $action,$model=null,array $details=[]):void {AuditLog::create(['user_id'=>$r->user()?->id,'action'=>$action,'subject_type'=>$model?get_class($model):null,'subject_id'=>$model?->id,'details'=>$details,'ip_address'=>$r->ip()]);}
 public function home(){return view('home',['categories'=>Category::where('is_active',true)->orderBy('sort_order')->get(),'products'=>Product::where('is_available',true)->where('is_featured',true)->latest()->take(6)->get(),'settings'=>RestaurantSetting::pluck('value','key')]);}
 public function menu(Request $r){$q=Product::with('category')->where('is_available',true);if($r->filled('category'))$q->whereHas('category',fn($x)=>$x->where('slug',$r->string('category')));if($r->filled('q'))$q->where('name','like','%'.$r->string('q').'%');return view('menu',['categories'=>Category::where('is_active',true)->orderBy('sort_order')->get(),'products'=>$q->orderBy('sort_order')->paginate(12)->withQueryString()]);}
 public function register(Request $r){$data=$r->validate(['name'=>'required|string|max:120','email'=>'required|email:rfc|max:190|unique:users','phone'=>'nullable|string|max:40','password'=>'required|string|min:12|confirmed']);$data['role']='customer';$u=User::create($data);Auth::login($u);$r->session()->regenerate();return redirect()->route('account');}
 public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required|string','role'=>['required',Rule::in(['super_admin','admin','staff','customer'])]]);$key='login:'.Str::lower($data['email']).'|'.$r->ip();if(RateLimiter::tooManyAttempts($key,5))return back()->withErrors(['email'=>'Too many attempts. Try again shortly.'])->onlyInput('email');if(!Auth::attempt(['email'=>$data['email'],'password'=>$data['password'],'is_active'=>true])||$r->user()->role!==$data['role']){RateLimiter::hit($key,60);Auth::logout();return back()->withErrors(['email'=>'The supplied sign-in details could not be verified.'])->onlyInput('email');}RateLimiter::clear($key);$r->session()->regenerate();$this->audit($r,'auth.login');return redirect()->route('dashboard');}
 public function logout(Request $r){$this->audit($r,'auth.logout');Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('home');}
 public function dashboard(Request $r){$u=$r->user();if($u->role==='customer')return redirect()->route('account');$orders=Order::with('items')->latest();if($u->role==='staff')$orders->whereIn('status',['pending','confirmed','preparing','ready','out_for_delivery']);$pendingOrders=Order::where('status','pending')->count();if($u->role==='staff')$pendingOrders=Order::whereIn('status',['pending','confirmed','preparing','ready','out_for_delivery'])->count();return view('dashboard',['orders'=>$orders->paginate(20),'pendingOrders'=>$pendingOrders,'pendingPayments'=>in_array($u->role,['admin','super_admin'])?PaymentSubmission::where('status','submitted')->count():null,'reservations'=>Reservation::where('status','pending')->count(),'user'=>$u]);}
 public function addCart(Request $r,Product $product){abort_unless($product->is_available,404);$data=$r->validate(['quantity'=>'required|integer|min:1|max:20']);$cart=$r->session()->get('cart',[]);$cart[$product->id]=min(20,($cart[$product->id]??0)+$data['quantity']);$r->session()->put('cart',$cart);return back()->with('success','Added to your basket.');}
 public function cart(Request $r){$ids=array_keys($r->session()->get('cart',[]));$items=Product::whereIn('id',$ids)->where('is_available',true)->get();return view('cart',['items'=>$items,'quantities'=>$r->session()->get('cart',[])]);}
 public function checkout(Request $r){$data=$r->validate(['name'=>'required|string|max:120','phone'=>'required|string|max:40','fulfillment'=>['required',Rule::in(['delivery','pickup'])],'address'=>'required_if:fulfillment,delivery|nullable|string|max:1000','notes'=>'nullable|string|max:1000','payment_method'=>'required|string|max:60']);$cart=$r->session()->get('cart',[]);abort_if(!$cart,422,'Your basket is empty.');$order=DB::transaction(function()use($r,$data,$cart){$products=Product::whereIn('id',array_keys($cart))->where('is_available',true)->lockForUpdate()->get()->keyBy('id');abort_if(count($cart)!==$products->count(),422,'A basket item is no longer available.');$sum=0;foreach($cart as $id=>$qty){abort_if($qty<1||$qty>20,422);$sum+=(float)$products[$id]->price*$qty;} $o=Order::create(['reference'=>'EP-'.Str::upper(Str::random(10)),'user_id'=>$r->user()->id,'customer_name'=>$data['name'],'phone'=>$data['phone'],'fulfillment'=>$data['fulfillment'],'address'=>$data['address']??null,'notes'=>$data['notes']??null,'payment_method'=>$data['payment_method'],'subtotal'=>$sum,'total'=>$sum,'status'=>'pending','payment_status'=>'awaiting_submission']);foreach($cart as $id=>$qty){$p=$products[$id];OrderItem::create(['order_id'=>$o->id,'product_id'=>$p->id,'name_snapshot'=>$p->name,'unit_price'=>$p->price,'quantity'=>$qty,'line_total'=>$p->price*$qty]);}OrderStatusHistory::create(['order_id'=>$o->id,'user_id'=>$r->user()->id,'to_status'=>'pending','note'=>'Order placed']);return $o;});$r->session()->forget('cart');return redirect()->route('orders.show',$order)->with('success','Order placed. Payment remains unverified until reviewed.');}
 public function account(Request $r){return view('account',['orders'=>$r->user()->orders()->with('items','payments')->latest()->paginate(10),'reservations'=>$r->user()->reservations()->latest()->get()]);}
 public function showOrder(Request $r,Order $order){abort_unless($r->user()->id===$order->user_id||in_array($r->user()->role,['admin','super_admin','staff']),404);return view('order',['order'=>$order->load('items','history','payments')]);}
 public function placeReservation(Request $r){$d=$r->validate(['name'=>'required|string|max:120','phone'=>'required|string|max:40','reservation_at'=>'required|date|after:now','guests'=>'required|integer|min:1|max:20','notes'=>'nullable|string|max:1000']);$res=Reservation::create($d+['reference'=>'RS-'.Str::upper(Str::random(10)),'user_id'=>$r->user()?->id,'status'=>'pending']);$this->audit($r,'reservation.created',$res);return back()->with('success','Reservation request received; it is pending confirmation.');}
 public function adminOrders(){return view('admin.orders',['orders'=>Order::with('items','customer')->latest()->paginate(25)]);}
 public function updateOrder(Request $r,Order $order){$d=$r->validate(['status'=>['required',Rule::in(['confirmed','preparing','ready','out_for_delivery','completed','cancelled'])],'note'=>'nullable|string|max:500']);$allowed=['pending'=>['confirmed','cancelled'],'confirmed'=>['preparing','cancelled'],'preparing'=>['ready','out_for_delivery','cancelled'],'ready'=>['completed','out_for_delivery','cancelled'],'out_for_delivery'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]];abort_unless(in_array($d['status'],$allowed[$order->status]??[],true),422,'Invalid status transition.');$old=$order->status;DB::transaction(function()use($order,$d,$old,$r){$order->update(['status'=>$d['status']]);OrderStatusHistory::create(['order_id'=>$order->id,'user_id'=>$r->user()->id,'from_status'=>$old,'to_status'=>$d['status'],'note'=>$d['note']??null]);});$this->audit($r,'order.status_changed',$order,['from'=>$old,'to'=>$d['status']]);return back()->with('success','Order status updated.');}
 public function submitPayment(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,404);$d=$r->validate(['method'=>'required|string|max:60','transaction_id'=>'required|string|max:120','amount_claimed'=>'required|numeric|min:0.01|max:9999999','paid_at'=>'nullable|date','evidence'=>'required|file|mimes:jpg,jpeg,png,pdf|max:5120','note'=>'nullable|string|max:1000']);$path=$r->file('evidence')->store('payments','local');$p=PaymentSubmission::create(['order_id'=>$order->id,'user_id'=>$r->user()->id,'method'=>$d['method'],'transaction_id'=>$d['transaction_id'],'amount_claimed'=>$d['amount_claimed'],'paid_at'=>$d['paid_at']??null,'evidence_path'=>$path,'note'=>$d['note']??null,'status'=>'submitted']);$order->update(['payment_status'=>'submitted']);$this->audit($r,'payment.submitted',$p);return back()->with('success','Evidence submitted for manual review; this is not confirmation of received funds.');}
 public function reviewPayment(Request $r,PaymentSubmission $payment){$d=$r->validate(['status'=>['required',Rule::in(['approved','rejected','further_information'])],'review_reason'=>'required|string|max:1000']);$payment->update($d+['reviewed_by'=>$r->user()->id,'reviewed_at'=>now()]);$payment->order->update(['payment_status'=>$d['status']]);$this->audit($r,'payment.reviewed',$payment,['status'=>$d['status']]);return back()->with('success','Review recorded. Confirm receipt independently before approval.');}
 public function paymentEvidence(Request $r,PaymentSubmission $payment){abort_unless(in_array($r->user()->role,['admin','super_admin'],true)||$payment->user_id===$r->user()->id,404);return Storage::disk('local')->download($payment->evidence_path);}
 public function reservations(){return view('admin.reservations',['reservations'=>Reservation::with('customer')->latest()->paginate(25)]);}
 public function reviewReservation(Request $r,Reservation $reservation){$d=$r->validate(['status'=>['required',Rule::in(['confirmed','rejected','cancelled'])]]);$reservation->update($d+['reviewed_by'=>$r->user()->id]);$this->audit($r,'reservation.reviewed',$reservation,$d);return back()->with('success','Reservation status updated.');}
 public function categories(){return view('admin.categories',['categories'=>Category::withCount('products')->orderBy('sort_order')->paginate(30)]);}
 public function saveCategory(Request $r,?Category $category=null){$d=$r->validate(['name'=>'required|string|max:100','description'=>'nullable|string|max:1000','sort_order'=>'nullable|integer|min:0']);$d['slug']=Str::slug($d['name']);$d['is_active']=true;$c=Category::updateOrCreate(['id'=>$category?->id],$d);$this->audit($r,'category.saved',$c);return back()->with('success','Category saved.');}
 public function products(){return view('admin.products',['products'=>Product::with('category')->latest()->paginate(30),'categories'=>Category::where('is_active',true)->get()]);}
 public function saveProduct(Request $r,?Product $product=null){$d=$r->validate(['category_id'=>'nullable|exists:categories,id','name'=>'required|string|max:120','description'=>'nullable|string|max:2000','price'=>'required|numeric|min:0.01|max:999999','is_available'=>'nullable|boolean','is_featured'=>'nullable|boolean','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:3072']);$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));$d['is_available']=$r->boolean('is_available');$d['is_featured']=$r->boolean('is_featured');if($r->hasFile('image'))$d['image_path']=$r->file('image')->store('products','public');$p=Product::updateOrCreate(['id'=>$product?->id],$d);$this->audit($r,'product.saved',$p);return back()->with('success','Product saved.');}
 public function customers(){return view('admin.customers',['customers'=>User::where('role','customer')->withCount('orders')->latest()->paginate(30)]);}
 public function setActive(Request $r,User $user){abort_if($user->role==='super_admin',403);$user->update(['is_active'=>!$user->is_active]);$this->audit($r,'user.activation_changed',$user,['active'=>$user->is_active]);return back();}
 public function ownerSetup(Request $r){$configured=User::where('role','super_admin')->exists();abort_if($configured,404);if($r->isMethod('get'))return view('auth.owner-setup');$d=$r->validate(['setup_secret'=>'required|string','name'=>'required|string|max:120','email'=>'required|email|unique:users','password'=>'required|string|min:14|confirmed']);$expected=(string)config('epicure.setup_secret','');abort_if(strlen($expected)<32||!hash_equals($expected,$d['setup_secret']),403);$user=DB::transaction(fn()=>User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>$d['password'],'role'=>'super_admin','is_active'=>true]));$this->audit($r,'owner.initial_setup',$user);Auth::login($user);$r->session()->regenerate();return redirect()->route('dashboard')->with('success','Owner account created. Remove EPICURE_SETUP_SECRET from server environment now.');}
 public function report(){return view('admin.report',['orders'=>Order::whereDate('created_at','>=',now()->subDays(30))->where('payment_status','approved')->get(),'approvedClaims'=>PaymentSubmission::whereDate('created_at','>=',now()->subDays(30))->where('status','approved')->sum('amount_claimed'),'statuses'=>Order::selectRaw('status,count(*) as count')->groupBy('status')->get(),'payments'=>PaymentSubmission::selectRaw('status,count(*) as count')->groupBy('status')->get()]);}
 public function paymentReviews(){return view('admin.payments',['payments'=>PaymentSubmission::with('order','customer')->latest()->paginate(25)]);}
 public function auditLogs(){return view('admin.audit',['logs'=>AuditLog::with('user')->latest('created_at')->paginate(50)]);}
}
